[CmdletBinding()]param([Parameter(Mandatory)][string]$RequestPath,[Parameter(Mandatory)][string]$ResponsePath)
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path;Import-Module (Join-Path $root 'ES/Automation/ABCD/ESABCDFrameworkParity.psm1') -Force;$requests=Get-Content -LiteralPath $RequestPath -Raw -Encoding UTF8|ConvertFrom-Json;$receipts=@();foreach($q in @($requests)){try{$r=Invoke-ESABCDFrameworkCapability -FrameworkId ([string]$q.frameworkId) -CapabilityId ([string]$q.capabilityId) -Payload $q.payload -EvidenceRef 'worker-request';$receipts+=,[pscustomobject][ordered]@{requestId=[string]$q.requestId;status='passed';receipt=$r}}catch{$receipts+=,[pscustomobject][ordered]@{requestId=[string]$q.requestId;status='failed';error=$_.Exception.Message}}};$out=[ordered]@{schemaVersion=1;worker='es-abcd-worker';pid=$PID;requestCount=@($requests).Count;receipts=$receipts};[IO.File]::WriteAllText([IO.Path]::GetFullPath($ResponsePath),($out|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false));if(@($receipts|Where-Object status -eq 'failed').Count){exit 1}
